/// Whether this is a name the picker could have produced.
///
/// The API checks it before storing one. The picker is the only control
/// surface that offers a name, but it is not the only way a request can
/// arrive — DR-0014.
pub fn is_known(name: &str) -> bool {
    ICON_NAMES.binary_search(&name).is_ok()
}
